# uptime-kuma

Uptime Kuma (TODO: one-line description)

Configuration, ports, data volumes, the compose snippet and the NixOS
options are generated into the docs site from `default.nix`. Write here
only what a person setting this up needs to know beyond that: first-login
steps, known differences between the container and a NixOS host, caveats.
# Inputs for the parity test (lib/checks/parity.nix), which boots the
# NixOS module under systemd and the image under podman with the SAME env
# file and requires the contract healthcheck to pass on both.
{ pkgs, lib, ... }:

{
  # Test values; must cover every `required = true` variable. Never real secrets.
  env = {
    # EXAMPLE_VAR = "test-value";
  };

  # Extra NixOS config for the `native` test machine only (e.g. a database
  # the service depends on).
  nixos = { };

  # Extra Python test steps; machines are `native` and `container`.
  testScript = "";
}
# The NixOS side. Prefer enabling and configuring the existing nixpkgs
# module over writing a systemd service by hand. Configuration the user
# controls must arrive as env vars (the contract) — set defaults in the
# contract, not here, so they apply to the container identically. Bind to
# 0.0.0.0 (via a contract default) so the container is reachable.
{ config, lib, pkgs, ... }:

let
  cfg = config.svc.uptime-kuma;
in
{
  config = lib.mkIf cfg.enable {
    # services.uptime-kuma.enable = true;
  };
}
# uptime-kuma — Uptime Kuma (TODO: one-line description)
#
# The contract below is the service's whole public surface: it drives the
# NixOS options every service gets (enable, environmentFile, openFirewall),
# the container image, the compose snippet, the docs page and the parity
# test. Field reference: lib/contract.nix.
{ svc }:

svc.mkService {
  name = "uptime-kuma";

  contract = {
    description = "Uptime Kuma (TODO: one-line description)";
    homepage = null; # "https://…"

    # "extracted": lift the systemd unit of the NixOS module into the image.
    # "modular":   run a nixpkgs modular service (system.services) directly.
    # Record why in upstream.json → decision.reason.
    approach = "extracted";
    unit = "uptime-kuma"; # systemd service to lift (approach = "extracted")
    # modularService = "uptime-kuma"; # name under system.services (approach = "modular")

    ports = [
      # { port = 8080; description = "Web UI"; }
    ];

    # Every variable a user may set. On NixOS they come from environmentFile,
    # in a container from -e / env_file / compose. A default applies on both.
    env = {
      # EXAMPLE_VAR = {
      #   description = "What it controls.";
      #   default = "value";      # or: required = true;
      #   secret = false;
      # };
    };

    # 2xx once the service is up; used by the image, compose and parity test.
    healthcheck = {
      port = 8080;
      path = "/";
    };
  };

  module = {
    imports = [
      ./options.nix
      ./configuration.nix
      ./scripts.nix
    ];
  };

  docker = import ./docker.nix;
  check = import ./check.nix;
  upstream = builtins.fromJSON (builtins.readFile ./upstream.json);
}
# Container-only needs. The image already gets the unit's StateDirectory as
# a volume, a non-root user (uid 1000), CA certs and /bin/sh. Add here only
# what the container needs on top.
{ pkgs, lib, ... }:

{
  # Extra persistent paths (beyond the unit's StateDirectory):
  volumes = [
    # { path = "/var/lib/uptime-kuma/uploads"; description = "Uploaded files"; }
  ];

  # Extra packages in the image (rarely needed; the unit's closure is already in):
  contents = [ ];

  # user = "1000:1000";
}
# Options beyond the standard ones every service already has:
#   svc.uptime-kuma.enable, .environmentFile, .openFirewall  (generated by lib/service.nix)
# Most services need nothing here — configuration belongs in env vars (the
# contract), because that's the only surface the container has. Add an
# option only for NixOS-host concerns that have no env-var equivalent.
{ lib, ... }:

{
  options.svc.uptime-kuma = {
  };
}
# Setup the service needs that isn't plain configuration: first-run
# initialisation, migrations, generating a config file from env vars.
# Hook it into the unit's preStart so it runs on NixOS AND in the container
# (the `extracted` image runs the unit's preStart before ExecStart). Scripts
# run as the service user and must be idempotent.
{ config, lib, pkgs, ... }:

let
  cfg = config.svc.uptime-kuma;
in
{
  config = lib.mkIf cfg.enable {
    # systemd.services.uptime-kuma.preStart = ''
    #   ...
    # '';
  };
}
{
  "app": "uptimekuma",
  "title": "Uptime Kuma",
  "source": "https://github.com/louislam/uptime-kuma",
  "upstream_commit": "45599d63ec1f6e40c255123a9943f8bf33feac9a",
  "scripts": {
    "ct": "ct/uptimekuma.sh",
    "install": "install/uptimekuma-install.sh"
  },
  "resources": {"cpu":1,"ram_mb":1024,"disk_gb":4,"os":"debian","os_version":"13"},
  "decision": {
    "approach": "extracted",
    "nixpkgs_package": null,
    "nixpkgs_module": null,
    "reason": ""
  }
}

